 const keys=['ArrowDown','ArrowDown',...Array(6).fill('ArrowRight'),...Array(6).fill('ArrowLeft'),'ArrowDown','ArrowUp','ArrowDown','ArrowDown','ArrowDown','ArrowDown',...Array(8).fill('ArrowRight'),...Array(10).fill('ArrowDown'),...Array(6).fill('ArrowLeft'),...Array(10).fill('ArrowUp'),'ArrowUp','ArrowUp','ArrowUp','ArrowUp','ArrowDown','ArrowDown'];
