 const run=await perf.evaluate(async keys=>{const samples=[],floor=[],paint=()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
  // Floor: the same two frames after a key nobody handles (frame quantization of this headless browser).
  for(let index=0;index<10;index++){const sent=performance.now();document.activeElement.dispatchEvent(new KeyboardEvent('keydown',{key:'F13',bubbles:true,cancelable:true}));await paint();floor.push(performance.now()-sent);await new Promise(resolve=>setTimeout(resolve,125));}
  window.__longTasks.length=0;
  for(const key of keys){const sent=performance.now();document.activeElement.dispatchEvent(new KeyboardEvent('keydown',{key,bubbles:true,cancelable:true}));await paint();samples.push({ms:performance.now()-sent,cards:document.querySelectorAll('main .card-open').length,where:document.activeElement.closest('.catalog-controls')?'chips':document.activeElement.closest('.catalog-grid')?'grid':document.activeElement.closest('.catalog-row')?'row':document.activeElement.closest('.focus-stage')?'banner':'other'});await new Promise(resolve=>setTimeout(resolve,125));}
  return {samples,floor:floor.sort((a,b)=>a-b)[9],longTasks:window.__longTasks.slice()};},keys);
 await cpu.send('Emulation.setCPUThrottlingRate',{rate:1});
 const times=run.samples.map(sample=>sample.ms).sort((a,b)=>a-b),p95=times[Math.ceil(times.length*.95)-1],maxCards=Math.max(...run.samples.map(sample=>sample.cards)),regions=[...new Set(run.samples.map(sample=>sample.where))];
 const liveRemote={cpuThrottle:4,moves:keys.length,regions,keyToSecondRAFP95Ms:Math.round(p95*10)/10,keyToSecondRAFMaxMs:Math.round(times.at(-1)*10)/10,noOpKeyToSecondRAFMaxMs:Math.round(run.floor*10)/10,longTasks:run.longTasks.length,longTaskMaxMs:Math.round(Math.max(0,...run.longTasks)),maxMountedCards:maxCards,byRegionMaxMs:Object.fromEntries(regions.map(region=>[region,Math.round(Math.max(...run.samples.filter(sample=>sample.where===region).map(sample=>sample.ms))*10)/10])),over33:run.samples.map((sample,index)=>sample.ms>33?`${index}:${keys[index]}:${sample.where}:${Math.round(sample.ms)}`:null).filter(Boolean)};console.log('liveRemote',JSON.stringify(liveRemote));
 assert.deepEqual(regions.filter(region=>['chips','row','grid'].includes(region)).sort(),['chips','grid','row']);assert.equal(run.longTasks.length,0,'no long tasks');// Target 33 ms; tolerated up to two 60 Hz frames + 1 ms (34.4), the same floor the banner-navigation rail run reports (34.5).
